    'eng.item.belirsizlik.sub': 'Netlik gelmeden adım atamamak',
    'eng.item.belirsizlik.panzehir': 'Belirsizlik herkesin hayatında var; mesele ona ettiğin tahammül. Perdenin üzerine yürü, içinden geç — diğer taraf o kadar da kötü değil.',
    'eng.item.belirsizlik.seed': 'Belirsizliğe tahammül edebilen bir kişi',
