    'eng.item.bulanik-dusunce.panzehir': 'Kendinle konuşmak, yazmak ya da sesini kaydetmek çoğu zaman iyi gelir. İstemediğin düşünceyi fark edip istediğinle değiş tokuş edebilirsin.',
    'eng.item.bulanik-dusunce.seed': 'Düşüncelerini netleştiren bir kişi',
    'eng.item.olumsuz-cevre.name': 'Olumsuz Çevre',
    'eng.item.olumsuz-cevre.sub': 'Çevre dışarıdan içeriye olumsuzlaştırır',
    'eng.item.olumsuz-cevre.panzehir': 'Önce kendine bak: nasıl bir insansan öyle insanlarla olursun. Sonra gerekirse çevreni seç.',
    'eng.item.olumsuz-cevre.seed': 'Çevresini bilinçle seçen bir kişi',
