    'eng.item.olumsuz-aliskanlik.sub': 'Sabah/akşam alışkanlıkların seni oluşturur',
    'eng.item.olumsuz-aliskanlik.panzehir': 'İstediğin alışkanlıkları seç. Ko-Zo: iyiye giden yolu kolaylaştır, kötüye gideni zorlaştır.',
    'eng.item.olumsuz-aliskanlik.seed': 'İyi alışkanlıkları olan bir kişi',
    'eng.item.erteleme.name': 'Erteleme Perdesi',
    'eng.item.erteleme.sub': '"Sonra yaparım" hayallerine çektiğin perde',
    'eng.item.erteleme.panzehir': 'Suya direkt atlar gibi başlayabilirsin. Ertelemenin arkasındaki korkuyu yazıp kısa hazzın uzun zararını görebilirsin.',
    'eng.item.erteleme.seed': 'Ertelemeyi sorunun kaynağı gören bir kişi',
    'eng.item.sikayet.name': 'Sürekli Şikayet',
    'eng.item.sikayet.sub': 'Sorumluluğu karşıya atmak',
    'eng.item.sikayet.panzehir': 'Tüm sorumluluğu al; her zaman yapabileceğin bir şey var. Şikayeti çözüme çevir.',
    'eng.item.sikayet.seed': 'Sorumluluğunu alan ve harekete geçen bir kişi',
    'eng.item.herkesi-memnun.name': 'Herkesi Memnun Etme',
    'eng.item.herkesi-memnun.sub': 'Boşa kürek çekmek',
    'eng.item.herkesi-memnun.panzehir': 'Gerektiğinde hayır de. Arkasındaki onay ihtiyacını fark et; herkesi memnun edemezsin.',
    'eng.item.herkesi-memnun.seed': 'Gerektiğinde hayır diyebilen bir kişi',
    'eng.item.kucumseme.name': 'Kendini Küçümseme / Büyütme',
    'eng.item.kucumseme.sub': 'Kibir = aşağılık kompleksi',
    'eng.item.kucumseme.panzehir': 'Herkesi insani değerde eşit görmek çoğu zaman huzur getirir. Kimsenin senden üstünlüğü veya aşağısı yok.',
    'eng.item.kucumseme.seed': 'Kendini ve herkesi eşit değerde gören bir kişi',
    'eng.item.kararsizlik.name': 'Kararsızlık',
    'eng.item.kararsizlik.sub': 'Karar vermemek de bir karardır',
    'eng.item.kararsizlik.panzehir': 'Her an seçiyorsun; kararsızlık diye bir şey yok. Karara haddini aşan önem yükleme.',
    'eng.item.kararsizlik.seed': 'Kararlarını kendi alan bir kişi',
    'eng.item.negatif-insan.name': 'Negatif İnsanlara Bağımlılık',
    'eng.item.negatif-insan.sub': 'Onlarla hayata sövmek',
    'eng.item.negatif-insan.panzehir': 'Dışarıdan gözlemle: bu birliktelik fayda mı zarar mı? Gerekirse açıkla ve uzaklaş.',
    'eng.item.negatif-insan.seed': 'Olumlu bir çevre kuran bir kişi',
    'eng.item.gecmiste-yasama.name': 'Geçmişte Yaşama',
    'eng.item.gecmiste-yasama.sub': 'Şimdiyi unutmak',
    'eng.item.gecmiste-yasama.panzehir': 'Geçmişten dersini al ve ilerle. Bugünün de bir geçmiş olacağını bilerek kıymetini bil.',
    'eng.item.gecmiste-yasama.seed': 'Şimdide yaşayan bir kişi',
