    'eng.item.kiyas.sub': 'Kendini başkasıyla ölçmek',
    'eng.item.kiyas.panzehir': 'Herkesin hayatı benzersiz. Ders/tavsiye al, sonra dön kendine odaklan: sen ne yapabilirsin?',
    'eng.item.kiyas.seed': 'Sadece dünkü kendiyle yarışan bir kişi',
    'eng.item.erteleme-t.name': 'Erteleme Tuzağı',
    'eng.item.erteleme-t.sub': 'Birikenlerin altında ezilmek',
    'eng.item.erteleme-t.panzehir': 'Ertelemeyi prensiple kır: ne zaman erteleyecek olsan direkt harekete geç.',
    'eng.item.erteleme-t.seed': 'Direkt harekete geçen bir kişi',
    'eng.item.sabirsizlik.name': 'Sabırsızlık Tuzağı',
    'eng.item.sabirsizlik.sub': 'Büyük ödüller sabredene',
    'eng.item.sabirsizlik.panzehir': 'Fiziki alemde değişim zaman alır. Sabret, hedefinin yolunda ısrarla ilerle.',
    'eng.item.sabirsizlik.seed': 'Sabırlı ve başarılı bir kişi',
    'eng.item.korku-t.name': 'Korku Tuzağı',
    'eng.item.korku-t.sub': 'Korkarak başaramamak',
    'eng.item.korku-t.panzehir': 'Her ihtimali kabul edip bir geri çekilme alanı kurarak harekete geçebilirsin.',
    'eng.item.korku-t.seed': 'Korkularını inceleyip yürüyen bir kişi',
    'eng.item.odak-kaybi.name': 'Odak Kaybı Tuzağı',
    'eng.item.odak-kaybi.sub': 'Aynı anda her şeyi yapmak',
    'eng.item.odak-kaybi.panzehir': 'Dikkatin bir tane. Tek tek, kaliteli ilerle — kalp ve zihinle uyumlu Süper Odak.',
    'eng.item.odak-kaybi.seed': 'Süper Odak\'ı olan bir kişi',
    'eng.item.gecmis-t.name': 'Geçmiş Tuzağı',
    'eng.item.gecmis-t.sub': 'Eski hatalarla yeni adımı engellemek',
    'eng.item.gecmis-t.panzehir': 'Geçmişe ders için bak; kendini güncelle ve yeni adımı at.',
    'eng.item.gecmis-t.seed': 'Geçmişten ders alıp ilerleyen bir kişi',
