    'gl.soz.iliski.bolluk.1': 'Bugün kıskançlık yerine paylaşmayı seçeceğim.',
    'gl.soz.iliski.default.0': 'Bugün bir ilişkimde ilk tepkimden önce üç nefes alacağım.',
    'gl.soz.iliski.default.1': 'Bugün bir yakınımı gerçekten dinleyeceğim.',
    'gl.soz.is.oz_sevgi.0': 'Bugün hatamı kendime kırbaç yapmadan kabul edeceğim.',
    'gl.soz.is.oz_sevgi.1': 'Bugün yorulduğumda kendime mola hakkı tanıyacağım.',
    'gl.soz.is.oz_saygi.0': 'Bugün işte bir kez, suçluluk duymadan sınırımı koruyacağım.',
    'gl.soz.is.oz_saygi.1': 'Bugün üstüme yıkılan tek bir işi nazikçe geri vereceğim.',
    'gl.soz.is.oz_deger.0': 'Bugün emeğimin karşılığını küçümsemeden sahipleneceğim.',
    'gl.soz.is.oz_deger.1': 'Bugün bir başarımı küçültmeden kabul edeceğim.',
    'gl.soz.is.oz_guven.0': 'Bugün ertelediğim tek zor işe 25 dakika vereceğim.',
    'gl.soz.is.oz_guven.1': 'Bugün fikrimi çekinmeden bir kez dile getireceğim.',
    'gl.soz.is.bolluk.0': 'Bugün fırsatı "bana göre değil" demeden değerlendireceğim.',
    'gl.soz.is.bolluk.1': 'Bugün kıtlık değil, yeterlilik gözüyle bakacağım.',
    'gl.soz.is.default.0': 'Bugün işime niyetimi seçerek başlayacağım.',
    'gl.soz.is.default.1': 'Bugün ertelediğim tek adımı atacağım.',
    'gl.gift.oz_sevgi.q0': 'Kendine bir dost gibi davranabilirsin — bugün denemeye ne dersin?',
    'gl.gift.oz_sevgi.q1': 'Olduğun kişiye sertlikle değil, şefkatle bakmak da bir seçim olabilir.',
    'gl.gift.oz_sevgi.para': 'Çoğu insan kendine, hiçbir dostuna reva görmeyeceği bir sertlikle konuşur. Oysa değişim, kendine yönelttiğin sesin tonunu değiştirmekle başlar. Mesele dışarıdaki değil — mesele sensin; ve kendine nasıl davrandığın, hayatına nasıl davranıldığının provası olabilir.',
    'gl.gift.oz_sevgi.article': 'Kendinle Konuşmak: İçindeki Sesin Tonu',
    'gl.gift.oz_saygi.q0': 'Sınır koymak, kendine saygının ilk cümlesi olabilir.',
    'gl.gift.oz_saygi.q1': 'Açıklama yığmadan "hayır" diyebilmek bir olgunluk gibi görünüyor.',
    'gl.gift.oz_saygi.para': 'Sınır, başkasını uzaklaştırmak değil; kendini içeride tutmak olabilir. Her "evet"in altında bir "hayır" ezilirse, zamanla kendi sesini duyamaz olursun. Saygı, önce kendine gösterilir; sonra dünyadan geri döner.',
    'gl.gift.oz_saygi.article': 'Sınır: Kendine Saygının İlk Cümlesi',
    'gl.gift.oz_deger.q0': 'Hak etmek için kanıtlamana gerek yok — yalnızca kabul edebilirsin.',
    'gl.gift.oz_deger.q1': 'Değerin, başardıklarının toplamından bağımsız olabilir.',
    'gl.gift.oz_deger.para': 'Değerini sürekli kanıtlamak zorunda hissediyorsan, hiçbir başarı yeterli gelmeyecektir; çünkü mesele başarı değil, içindeki "yetmezlik" inancı olabilir. Olduğun kişiye göre bir hayatın olur — ve sen, kanıtlamadan da değerlisin.',
    'gl.gift.oz_deger.article': 'Hak Etmek: Kanıtlamadan Var Olmak',
    'gl.gift.oz_guven.q0': 'Cesaret, korkuyla birlikte hareket etmek olabilir.',
    'gl.gift.oz_guven.q1': 'Bir adım küçük görünür; ama yönü değiştiren, adımın kendisi olabilir.',
    'gl.gift.oz_guven.para': 'Güven, korkunun yokluğu değildir; korkuya rağmen atılan adım olabilir. İlk adımı attığında beyin, "demek yapabiliyormuşum" diye yeni bir kanıt yazar. Güven, eylemden önce değil, eylemden sonra gelir.',
    'gl.gift.oz_guven.article': 'Cesaret: Korkuyla Birlikte Yürümek',
    'gl.gift.bolluk.q0': 'Bolluk paylaştıkça çoğalır; önce kendine ver.', /* IHTIMAL-MUAF: aforizma — "Bolluk paylaştıkça çoğalır" kitap dili (§3.1) */
    'gl.gift.bolluk.q1': 'Kıtlık bir gerçeklik değil, bir bakış olabilir.',
    'gl.gift.bolluk.para': 'Kıtlık zihni, her şeyi "yetmez" diye okur; bolluk zihni ise "yeter, hatta artar" der. Bu bir saflık değil, bir karar olabilir. Şükür, bolluğun kapısını açan ilk anahtardır — çünkü sahip olduğunu görmeyen, gelecek olanı da fark edemez.',
    'gl.gift.bolluk.article': 'Bolluk Bilinci: Kıtlıktan Çıkış',
    'gl.gift.default.q0': 'Bugün olduğun kişi, yarın olacağın kişinin tohumu gibi görünüyor.',
    'gl.gift.default.q1': 'Mesele dışarıdaki değil — mesele sensin; ve sen değişebilirsin.',
    'gl.gift.default.para': 'Değişim büyük bir karar anında değil, küçük ve tutarlı seçimlerin üst üste binmesiyle olur. Niyet eylemden öncedir: sabah önce niyetini seç, sonra gün seni değil, sen günü yön ver.',
    'gl.gift.default.article': 'Mesele Sensin: Değişimin Çekirdeği',
