    /* ─── 10v Manifesto Okuma (mr.*) — chrome + 12 madde (kitap içeriği) ─── */
    'mr.call': 'ZİHNİYET DEVRİMİNE ÇAĞRI',
    'mr.complete': 'TAMAMLA · MÜHÜRLE',
    'mr.goto_full': 'Tam Manifestoyu Oku → 12 Mühür',
    'mr.next': 'İLERİ →',
    'mr.toast': 'Manifesto okundu · Hayal Mührü beslendi ◉',
    'mr.sealed': 'MÜHÜRLÜ',
    'mr.open_seal': 'AÇIK MÜHÜR',
    'mr.prev': 'ÖNCEKİ',
    'mr.next_nav': 'SONRAKİ',
    'mr.item.0.name': 'Hakikat',
    'mr.item.0.title': 'Mesele Sensin',
    'mr.item.0.summary': 'Hayatında değiştirmek istediğin her şeyin kaynağı dışarıda değil, içindedir. Koşullar, insanlar ya da şans seni belirlemez; olduğun kişi belirler. Dönüşümün ilk ve tek gerçek adımı bunu kabul etmektir.',
    'mr.item.1.name': 'Hayal',
    'mr.item.1.title': 'Hayal Alemi Hayal Değildir',
    'mr.item.1.summary': 'Zihinde canlı tutulan hayaller gerçekliği şekillendiren en güçlü araçtır. Hayal kurmak kaçmak değil, olmak istediğin kişiyi önceden yaşamaktır. Zihnin inşa ettiği her şey, bir gün ellerin inşa edeceğinin planıdır.',
    'mr.item.2.name': 'Uyum',
    'mr.item.2.title': 'Kalp ve Zihin Birlikte Olmalıdır',
    'mr.item.2.summary': 'Ne yalnızca mantık ne de yalnızca his tek başına yeterlidir; ikisi uyum içinde çalıştığında gerçek güç ortaya çıkar. Kalbinin duymadığı kararlar uzun vadede sürdürülemez; zihninin onaylamadığı duygular seni sürükler. Bütünlük, ikisini aynı anda konuşturabilmektir.',
    'mr.item.3.name': 'Ayna',
    'mr.item.3.title': 'İnançlar Hayatın Belirleyicisidir',
    'mr.item.3.summary': 'Gerçek olmayan ama gerçekmiş gibi hissettiren inançlar seni görünmez bir kafeste tutar. Hangi inancı beslersin, o inanç hangi gerçekliği yaratacağını belirler. İnançlarını değiştirmek, kaderini değiştirmektir.',
    'mr.item.4.name': 'Sarmal',
    'mr.item.4.title': 'Düşünceler Başlangıç Noktasıdır',
    'mr.item.4.summary': 'Her duygu bir düşünceden, her davranış bir duyguden, her sonuç bir davranıştan doğar. Zincirin ilk halkası daima bir düşüncedir; dolayısıyla hayatını değiştirmek istiyorsan düşüncenle başla. Zihnini fark etmeden özgür olamazsın.',
    'mr.item.5.name': 'Adak',
    'mr.item.5.title': 'Hayat Seçimlerden Oluşur',
    'mr.item.5.summary': 'Büyük kaderler büyük anlarda değil, her günün küçük seçimlerinde şekillenir. Ne yiyeceğinden kime vakit ayıracağına kadar her seçim seni olmak istediğin kişiye ya yaklaştırır ya da uzaklaştırır. Seçimsiz geçen hiçbir an yoktur; hareketsizlik de bir seçimdir.',
    'mr.item.6.name': 'Gölge',
    'mr.item.6.title': 'Sorunların Kaynağı Olunan Kişidir',
    'mr.item.6.summary': 'Sorunlar tesadüf değil; olduğun kişinin bir yansımasıdır. Çevreyi, koşulları ya da başkalarını değiştirmek sorunun kaynağını çözmez. Kişiyi değiştirmek, sorunların kendiliğinden çözüldüğünü görmektir.',
    'mr.item.7.name': 'Hak',
    'mr.item.7.title': 'İstenen Hayatı O Hayatı Hak Eden Yaşar',
    'mr.item.7.summary': 'Arzuladığın hayat, sahip olduğun koşulların değil, olduğun kişinin hak ettiği kadar gerçektir. O hayatı yaşamak için önce o hayatı yaşayan kişi olmak gerekir. Varış noktası değil, yolcunun kim olduğu belirleyicidir.',
    'mr.item.8.name': 'Cesaret',
    'mr.item.8.title': 'Hayatının Sorumluluğu Sende',
    'mr.item.8.summary': 'Mağdur olmak bir hikâye; sorumluluğu almak bir seçimdir. Her şey olmayabilir senin elinde, ama verdiğin tepki, yorumladığın anlam ve attığın adım daima öyledir. Sorumluluğu almak suçlamak değil; gücü geri almaktır.',
    'mr.item.9.name': 'Elmas',
    'mr.item.9.title': 'Toplum İçin Kendini En İyi Biçimde Yetiştir',
    'mr.item.9.summary': 'Bir insanın topluluğuna verebileceği en büyük armağan, en iyi versiyonuna ulaşmış kendi benliğidir. Güçlü, bütünleşmiş ve bilinçli bir kişi çevresini de güçlendirir. Kendine yatırım yapmak bencillik değil; toplumsal bir sorumluluktur.',
    'mr.item.10.name': 'Adalet',
    'mr.item.10.title': 'Hak, Hukuk ve Adalet Her Toplumun Temelidir',
    'mr.item.10.summary': 'Bireysel dönüşüm toplumsal bir zemine ihtiyaç duyar; adalet olmadan insan potansiyeli tam açılamaz. Kendi haklarını bilmek ve başkasının hakkını korumak, olgun bir insanın vazgeçilmez koşuludur. İç dünya kadar dış dünya da inşa edilmeyi hak eder.',
    'mr.item.11.name': 'İman',
    'mr.item.11.title': 'Allah İnsanlarladır, Sen Yalnız Değilsin',
    'mr.item.11.summary': 'En derin dönüşümün anlarında bile yalnız değilsin; anlam ve destek daha büyük bir kaynaktan gelir. Bu bilinç hem tevekküle hem cesarete zemin hazırlar. Mesele sensin — ama sen de çok daha büyük bir bütünün parçasısın.',

